				cell := batchInsertCell{column: `states`, set: true}
				jsonValue, err := marshalArrayOfArraysFieldValue(input.States)
				if err != nil {
					return nil, fmt.Errorf("failed to marshal JSON field states: %w", err)
				}
				cell.value = jsonValue
